 52    when:
 53      java.referenced:
 54        pattern: org.springframework.util.concurrent.ListenableFuture*
 55        location: IMPORT
 56    description: ListenableFuture and related types are deprecated since Spring Framework 6.0  
 57    message: |
 58      Spring Framework 6.0 has deprecated support for ListenableFuture and related types (ListenableFutureCallback, SettableListenableFuture, etc.)
 59      The reason for deprecation is the introduction of CompletableFuture in Java 8, which offers a richer set of features and better integration with the Java ecosystem.
 60      java.util.concurrent.CompletableFuture is now the recommended way to handle asynchronous operations in Spring applications.
 61      
 62      An example of a migration would be:
 63      
 64      Before migration:
 65      ```
 66          import org.springframework.util.concurrent.ListenableFuture;
 67          import org.springframework.util.concurrent.ListenableFutureCallback;
 68          import org.springframework.util.concurrent.SettableListenableFuture;
 69  
 70          public class ListenableFutureExample {
 71  
 72              public static void main(String[] args) {
 73                  SettableListenableFuture<String> future = new SettableListenableFuture<>();
 74  
 75                  future.addCallback(new ListenableFutureCallback<String>() {
 76                      @Override
 77                      public void onSuccess(String result) {
 78                          System.out.println("Success: " + result);
 79                      }
 80  
 81                      @Override
 82                      public void onFailure(Throwable ex) {
 83                          System.out.println("Failure: " + ex.getMessage());
 84                      }
 85                  });
 86  
 87                  // Simulate asynchronous operation
 88                  new Thread(() -> {
 89                      try {
 90                          Thread.sleep(1000);
 91                          future.set("Hello, World!");
 92                      } catch (InterruptedException e) {
 93                          future.setException(e);
 94                      }
 95                  }).start();
 96              }
 97          }
 98          
 99      ```
100      
101      After migration:
102      ```
103          import java.util.concurrent.CompletableFuture;
104  
105          public class CompletableFutureExample {
106            public static void main(String[] args) {
107              CompletableFuture<String> future = new CompletableFuture<>();
108  
109              future.whenComplete((result, ex) -> {
110                if (ex != null) {
111                  System.out.println("Failure: " + ex.getMessage());
112                } else if (result != null) {
113                  System.out.println("Success: " + result);
114                }
115              });
116  
117              // Simulate asynchronous operation
118              new Thread(() -> {
119                try {
120                  // Thread.currentThread().interrupt();
121                  Thread.sleep(1000);
122                  future.complete("Hello, World!");
123                } catch (InterruptedException e) {
124                  future.completeExceptionally(e);
125                }
